1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Scenario = {
14	  customer: { yearsWithMHPCO: number };
15	  steps: QuoteStep[];
16	};
17	
18	export type ScenarioResult = {
19	  results: unknown[];
20	};
21	
22	const PROCESSING_FEE = 5;
23	const FIRST_INSURANCE_SURCHARGE = 0.1;
24	
25	/** Premiums round up — in the MHPCO's favour. Float noise is discarded first. */
26	const roundUpToWholeG = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
27	
28	const BASE_PREMIUMS: Record<string, number> = {
29	  sword: 100,
30	  amulet: 60,
31	};
32	
33	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
34	
35	const quotePremium = (items: Item[]): number => {
36	  const policyBase = items.reduce((sum, item) => sum + basePremiumOf(item), 0);
37	  const premiumBeforeFee = policyBase * (1 + FIRST_INSURANCE_SURCHARGE);
38	  return roundUpToWholeG(premiumBeforeFee + PROCESSING_FEE);
39	};
40	
41	export const runScenario = (scenario: Scenario): ScenarioResult => {
42	  return { results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })) };
43	};
